package fleet

// Remote diagnostics HTTP handlers. A fleet operator creates and cancels
// tasks and reads lists, details and audit trails; the simulated device claims
// the earliest claimable task and reports its outcome. Task operations never
// touch telemetry, rules, configuration or device activity times.

import (
	"encoding/json"
	"errors"
	"net/http"
	"strconv"
	"strings"
)

// taskCreateRequest is the raw task creation envelope.
type taskCreateRequest struct {
	RequestID       string `json:"requestId"`
	DurationSeconds *int   `json:"durationSeconds"`
}

// taskReportRequest is the device outcome envelope.
type taskReportRequest struct {
	ReceiptID  string          `json:"receiptId"`
	Credential string          `json:"credential"`
	Success    *bool           `json:"success"`
	Reason     string          `json:"reason"`
	Result     json.RawMessage `json:"result"`
}

func (h *handler) createTask(w http.ResponseWriter, r *http.Request) {
	var request taskCreateRequest
	if err := decodeSingleJSON(r, &request); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
		return
	}
	requestID := strings.TrimSpace(request.RequestID)
	if requestID == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "requestId is required"})
		return
	}
	if request.DurationSeconds == nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "durationSeconds is required"})
		return
	}
	if *request.DurationSeconds < taskMinDuration || *request.DurationSeconds > taskMaxDuration {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "durationSeconds must be between 1 and 60"})
		return
	}

	task, repeat, err := h.store.CreateTask(r.PathValue("id"), requestID, *request.DurationSeconds)
	if errors.Is(err, ErrDeviceNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrTaskConflict) {
		writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrStorageUnavailable) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	status := http.StatusCreated
	if repeat {
		status = http.StatusOK
	}
	writeJSON(w, status, task)
}

func (h *handler) listTasks(w http.ResponseWriter, r *http.Request) {
	tasks, err := h.store.ListTasks(r.PathValue("id"))
	if errors.Is(err, ErrDeviceNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrStorageUnavailable) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"tasks": tasks})
}

func (h *handler) getTask(w http.ResponseWriter, r *http.Request) {
	taskID, err := parseTaskID(r)
	if err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "taskId must be a positive integer"})
		return
	}
	task, err := h.store.GetTask(r.PathValue("id"), taskID)
	if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrTaskNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrStorageUnavailable) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	writeJSON(w, http.StatusOK, task)
}

// claimTask serves the simulated device's pull. Only the earliest-created task
// that has reached its claimable time is returned; 204 means nothing is
// claimable (including when another task is still executing).
func (h *handler) claimTask(w http.ResponseWriter, r *http.Request) {
	view, claimed, err := h.store.ClaimTask(r.PathValue("id"))
	if errors.Is(err, ErrDeviceNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrStorageUnavailable) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	if !claimed {
		w.WriteHeader(http.StatusNoContent)
		return
	}
	writeJSON(w, http.StatusOK, view)
}

func (h *handler) reportTask(w http.ResponseWriter, r *http.Request) {
	taskID, err := parseTaskID(r)
	if err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "taskId must be a positive integer"})
		return
	}
	var request taskReportRequest
	if err := decodeSingleJSON(r, &request); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
		return
	}
	receiptID := strings.TrimSpace(request.ReceiptID)
	if receiptID == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "receiptId is required"})
		return
	}
	credential := strings.TrimSpace(request.Credential)
	if credential == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "credential is required"})
		return
	}
	if request.Success == nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "success is required"})
		return
	}
	reason := strings.TrimSpace(request.Reason)
	var result json.RawMessage
	if *request.Success {
		if len(request.Result) == 0 || !isJSONObject(request.Result) {
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "a successful report requires a JSON object result"})
			return
		}
		result = request.Result
	} else if reason == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "a failed report requires a non-blank reason"})
		return
	}

	report, repeat, err := h.store.ReportTask(r.PathValue("id"), taskID, receiptID, credential, *request.Success, reason, result)
	if errors.Is(err, ErrDeviceNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrTaskNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrTaskConflict) {
		writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrStorageUnavailable) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	status := http.StatusCreated
	if repeat {
		status = http.StatusOK
	}
	writeJSON(w, status, report)
}

func (h *handler) cancelTask(w http.ResponseWriter, r *http.Request) {
	taskID, err := parseTaskID(r)
	if err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "taskId must be a positive integer"})
		return
	}
	task, err := h.store.CancelTask(r.PathValue("id"), taskID)
	if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrTaskNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrTaskConflict) {
		writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrStorageUnavailable) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	writeJSON(w, http.StatusOK, task)
}

func (h *handler) listTaskAudit(w http.ResponseWriter, r *http.Request) {
	taskID, err := parseTaskID(r)
	if err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "taskId must be a positive integer"})
		return
	}
	audit, err := h.store.ListTaskAudit(r.PathValue("id"), taskID)
	if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrTaskNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrStorageUnavailable) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"audit": audit})
}

func parseTaskID(r *http.Request) (int64, error) {
	taskID, err := strconv.ParseInt(r.PathValue("taskId"), 10, 64)
	if err != nil || taskID < 1 {
		return 0, err
	}
	return taskID, nil
}

package fleet

import (
	"fmt"
	"net/http"
	"testing"
	"time"
)

// --- restart restores the whole task state -----------------------------------

func TestPersistentTaskCreateRestores(t *testing.T) {
	dir := t.TempDir()
	store := openPersistent(t, dir)
	h := NewHandler(store)
	mustRegister(t, h, "gw")

	createTask(t, h, "gw", taskBody("req-1", 30), http.StatusCreated)
	createTask(t, h, "gw", taskBody("req-2", 45), http.StatusCreated)
	if err := store.Close(); err != nil {
		t.Fatal(err)
	}

	store2 := reopenPersistent(t, dir)
	h2 := NewHandler(store2)

	list := decodeBody[struct {
		Tasks []taskResponse `json:"tasks"`
	}](t, doRequest(t, h2, http.MethodGet, "/v1/devices/gw/tasks", ""))
	if len(list.Tasks) != 2 || list.Tasks[0].ID != 1 || list.Tasks[1].ID != 2 {
		t.Fatalf("tasks after restart = %+v", list.Tasks)
	}
	if list.Tasks[0].Status != "pending" || list.Tasks[0].DurationSeconds != 30 {
		t.Fatalf("task 1 after restart = %+v", list.Tasks[0])
	}

	// requestId dedup survives: same content -> 200, different duration -> 409.
	createTask(t, h2, "gw", taskBody("req-1", 30), http.StatusOK)
	createTask(t, h2, "gw", taskBody("req-1", 45), http.StatusConflict)

	// Audit survives with the create record.
	audit := listAudit(t, h2, "gw", 1)
	if len(audit) != 1 || audit[0].Event != "created" || audit[0].ToStatus != "pending" {
		t.Fatalf("audit after restart = %+v", audit)
	}
}

func TestPersistentTaskClaimRestoresAndTimesOut(t *testing.T) {
	dir := t.TempDir()
	store := openPersistent(t, dir)
	h := NewHandler(store)
	mustRegister(t, h, "gw")
	createTask(t, h, "gw", taskBody("req-1", 5), http.StatusCreated)
	claim := claimTask(t, h, "gw", http.StatusOK)
	claimedAt := claim.Task.ClaimedAt
	deadline := claim.Deadline
	if err := store.Close(); err != nil {
		t.Fatal(err)
	}

	// Reopen with a much later clock: the in-progress task is past its deadline.
	store2 := reopenPersistent(t, dir)
	h2 := NewHandler(store2)

	task := getTask(t, h2, "gw", 1, http.StatusOK)
	if task.Status != "waiting" || task.FailureReason != "deadline exceeded" {
		t.Fatalf("task after restart should be timed out: %+v", task)
	}
	if task.Attempts != 1 {
		t.Fatalf("attempts after restart = %d, want 1", task.Attempts)
	}
	// The deadline and the wait are not reset.
	if task.NextClaimableAt.IsZero() || !task.NextClaimableAt.Equal(deadline.Add(1*time.Second)) {
		t.Fatalf("next claimable after restart = %s, want %s", task.NextClaimableAt, deadline.Add(1*time.Second))
	}
	_ = claimedAt

	// The timeout is recorded exactly once: re-reading does not duplicate it.
	audit := listAudit(t, h2, "gw", 1)
	events := []string{}
	for _, rec := range audit {
		events = append(events, rec.Event)
	}
	if got := joinEvents(events); got != "created,claimed,timed_out" {
		t.Fatalf("audit after restart = %s", got)
	}
	if audit[2].Attempt != 1 || audit[2].FromStatus != "in_progress" || audit[2].ToStatus != "waiting" {
		t.Fatalf("timeout audit record = %+v", audit[2])
	}

	// The released device can claim again.
	claim2 := claimTask(t, h2, "gw", http.StatusOK)
	if claim2.Attempt != 2 {
		t.Fatalf("re-claim attempt = %d, want 2", claim2.Attempt)
	}
}

func TestPersistentTaskReportRestores(t *testing.T) {
	dir := t.TempDir()
	store := openPersistent(t, dir)
	h := NewHandler(store)
	mustRegister(t, h, "gw")
	createTask(t, h, "gw", taskBody("req-1", 30), http.StatusCreated)
	claim := claimTask(t, h, "gw", http.StatusOK)
	reportTask(t, h, "gw", claim.Task.ID,
		reportBody("rcpt-1", claim.Credential, true, "", `{"ok":true,"n":7}`), http.StatusCreated)
	if err := store.Close(); err != nil {
		t.Fatal(err)
	}

	store2 := reopenPersistent(t, dir)
	h2 := NewHandler(store2)

	task := getTask(t, h2, "gw", 1, http.StatusOK)
	if task.Status != "succeeded" || task.Result == nil || task.CompletedAt == nil {
		t.Fatalf("task after restart = %+v", task)
	}
	if string(task.Result) != `{"ok":true,"n":7}` {
		t.Fatalf("result after restart = %s", task.Result)
	}

	// Receipt dedup survives: same content -> 200, different -> 409.
	reportTask(t, h2, "gw", 1,
		reportBody("rcpt-1", claim.Credential, true, "", `{"n":7,"ok":true}`), http.StatusOK)
	reportTask(t, h2, "gw", 1,
		reportBody("rcpt-1", claim.Credential, true, "", `{"ok":false}`), http.StatusConflict)

	// Audit survives.
	audit := listAudit(t, h2, "gw", 1)
	if got := joinEvents(eventsOf(audit)); got != "created,claimed,succeeded" {
		t.Fatalf("audit after restart = %s", got)
	}
}

