	var wg sync.WaitGroup
	successes := make(chan int, 10)
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			r := doRequest(t, h, http.MethodPost, "/v1/devices/dev-1/tasks/claim", "")
