360		// Restore the good journal, then add a torn 5-byte tail: it must be
361		// trimmed without losing committed state.
362		if err := os.WriteFile(filepath.Join(dir, commitName), append(goodJournal, 1, 2, 3, 4, 5), 0o600); err != nil {
363			t.Fatal(err)
364		}
365		store3 := reopenPersistent(t, dir)
366		if !store3.Exists("gw") {
367			t.Fatalf("device lost while trimming torn journal tail")
368		}
369	}
370	
371	func TestPersistentUnsupportedVersionFailsStartup(t *testing.T) {
372		dir := t.TempDir()
373		store := openPersistent(t, dir)
374		mustRegister(t, NewHandler(store), "gw")
375		if err := store.Close(); err != nil {
376			t.Fatal(err)
377		}
378		raw := walRaw(t, dir)
379		raw[8] = 99
380		if err := os.WriteFile(filepath.Join(dir, walName), raw, 0o600); err != nil {
381			t.Fatal(err)
382		}
383		if _, err := NewPersistentStore(dir); err == nil || !strings.Contains(err.Error(), "unsupported format version") {
384			t.Fatalf("got %v, want unsupported version error", err)
385		}
386	}
387	
388	// --- torn/unacknowledged tail is discarded, committed prefix survives -------
389	
390	func TestPersistentTornTailIsDiscarded(t *testing.T) {
391		dir := t.TempDir()
392		store := openPersistent(t, dir)
393		h := NewHandler(store)
394		mustRegister(t, h, "gw")
395		if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay",
396			replayBody("b1", sample("e1", "2024-01-02T10:00:00Z", `{"v":1}`))); r.Code != http.StatusAccepted {
397			t.Fatalf("seed = %d", r.Code)
398		}
399		if err := store.Close(); err != nil {
400			t.Fatal(err)
401		}
402	
403		// Simulate a process killed mid-write: a partial frame with no marker.
404		f, err := os.OpenFile(filepath.Join(dir, walName), os.O_WRONLY|os.O_APPEND, 0o600)
405		if err != nil {
406			t.Fatal(err)
407		}
408		if _, err := f.Write([]byte{0x05, 0x00, 0x00, 0x00, recReplay, 'x'}); err != nil {
409			t.Fatal(err)
410		}
411		if err := f.Close(); err != nil {
412			t.Fatal(err)
413		}
414	
415		store2 := reopenPersistent(t, dir)
416		h2 := NewHandler(store2)
417		events := allEvents(t, h2, "gw")
418		if len(events) != 1 || events[0].Sequence != 1 {
419			t.Fatalf("committed event lost across torn tail: %+v", events)
420		}
421		// Sequence space is not consumed by the torn write.
422		if r := doRequest(t, h2, http.MethodPost, "/v1/devices/gw/replay",
423			replayBody("b2", sample("e2", "2024-01-02T11:00:00Z", `{"v":2}`))); r.Code != http.StatusAccepted {
424			t.Fatalf("write after torn tail = %d: %s", r.Code, r.Body.String())
425		}
426		events = allEvents(t, h2, "gw")
427		if len(events) != 2 || events[1].Sequence != 2 {
428			t.Fatalf("sequence after torn tail = %+v", events)
429		}
430	}
