432	// --- runtime write failure returns 503 and changes nothing ------------------
433	
434	type failingWAL struct {
435		inner    *walFile
436		failOnce bool
437		mu       sync.Mutex
438		didFail  bool
439	}
440	
441	func (w *failingWAL) appendRecord(recType byte, value any) error {
442		w.mu.Lock()
443		defer w.mu.Unlock()
444		if !w.didFail {
445			w.didFail = true
446			// Leave residue from an interrupted write at the committed offset,
447			// without a commit-journal entry and without advancing durable.
448			if err := pwriteAll(w.inner.walF, []byte{0xff, 0xff, 0xff, 0xff, 0x12}, w.inner.walDurable); err != nil {
449				return err
450			}
451			return fmt.Errorf("simulated disk failure")
452		}
453		return w.inner.appendRecord(recType, value)
454	}
455	
456	func TestPersistentWriteFailureReturns503AndRetries(t *testing.T) {
457		dir := t.TempDir()
458		store := openPersistent(t, dir)
459		h := NewHandler(store)
460		mustRegister(t, h, "gw")
461	
462		// Fail the first telemetry write at the storage layer.
463		real := store.wal.(*walFile)
464		failing := &failingWAL{inner: real}
465		store.wal = failing
466	
467		r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/telemetry", `{"temperature":1}`)
468		if r.Code != http.StatusServiceUnavailable {
469			t.Fatalf("failing write status = %d, want 503: %s", r.Code, r.Body.String())
470		}
471	
472		// Queryable state is unchanged and no sequence was consumed.
473		events := allEvents(t, h, "gw")
474		if len(events) != 0 {
475			t.Fatalf("failed write left events: %+v", events)
476		}
477	
478		// Once writes succeed again, the same request commits at sequence 1 and
479		// overwrites the residue the failed attempt left behind.
480		r = doRequest(t, h, http.MethodPost, "/v1/devices/gw/telemetry", `{"temperature":1}`)
481		if r.Code != http.StatusAccepted {
482			t.Fatalf("retried write = %d: %s", r.Code, r.Body.String())
483		}
484		events = allEvents(t, h, "gw")
485		if len(events) != 1 || events[0].Sequence != 1 {
486			t.Fatalf("retry did not commit at sequence 1: %+v", events)
487		}
488	
489		// A failing replay must not reserve sequences or leave a receipt.
490		failing.didFail = false
491		r = doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay",
492			replayBody("batch-x", sample("x1", "2024-01-03T10:00:00Z", `{"v":9}`)))
493		if r.Code != http.StatusServiceUnavailable {
494			t.Fatalf("failing replay = %d, want 503", r.Code)
495		}
496		events = allEvents(t, h, "gw")
497		if len(events) != 1 {
498			t.Fatalf("failed replay consumed a sequence: %+v", events)
499		}
500		r = doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay",
501			replayBody("batch-x", sample("x1", "2024-01-03T10:00:00Z", `{"v":9}`)))
502		if r.Code != http.StatusAccepted {
503			t.Fatalf("retry of failed replay = %d, want 202 (no prior receipt): %s", r.Code, r.Body.String())
504		}
505		events = allEvents(t, h, "gw")
506		if len(events) != 2 || events[1].Sequence != 2 {
507			t.Fatalf("replay retry sequence = %+v", events)
508		}
509	
510		// Reopening the real log proves the residue never became visible.
511		store.wal = real
512		if err := store.Close(); err != nil {
513			t.Fatal(err)
514		}
515		store2 := reopenPersistent(t, dir)
516		h2 := NewHandler(store2)
517		events = allEvents(t, h2, "gw")
518		if len(events) != 2 {
519			t.Fatalf("recovered history = %+v", events)
520		}
521	}
522	
523	// --- replay batch atomicity across a crash ----------------------------------
524	func TestPersistentReplayIsOneCommitUnit(t *testing.T) {
525		dir := t.TempDir()
526		store := openPersistent(t, dir)
527		h := NewHandler(store)
528		mustRegister(t, h, "gw")
529	
530		// Commit a three-sample batch, then append a complete frame for another
531		// batch WITHOUT a commit-journal entry (phase 1 survived, phase 2 did not):
532		// recovery must expose none of it.
533		good := replayBody("good",
534			sample("g1", "2024-01-02T10:00:00Z", `{"v":1}`),
535			sample("g2", "2024-01-02T11:00:00Z", `{"v":2}`),
536			sample("g3", "2024-01-02T12:00:00Z", `{"v":3}`),
537		)
538		if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay", good); r.Code != http.StatusAccepted {
539			t.Fatalf("good batch = %d", r.Code)
540		}
541		if err := store.Close(); err != nil {
542			t.Fatal(err)
543		}
544	
545		// Hand-craft a journal-less frame for another batch and append it.
546		body, err := marshalFrame(recReplay, walReplay{
547			DeviceID: "gw",
548			BatchID:  "lost",
549			Samples: []walSample{
550				{EventID: "l1", ObservedAt: time.Date(2024, 1, 4, 0, 0, 0, 0, time.UTC), Values: map[string]float64{"v": 4}},
551			},
552			Receipt: ReplayReceipt{
553				BatchID:      "lost",
554				NewCount:     1,
555				SampleStatus: []SampleStatus{{EventID: "l1", Sequence: 4, Duplicate: false}},
556			},
557		})
558		if err != nil {
559			t.Fatal(err)
560		}
561		raw := walRaw(t, dir)
562		raw = append(raw, body...) // frame present, but absent from commit.log
563		if err := os.WriteFile(filepath.Join(dir, walName), raw, 0o600); err != nil {
564			t.Fatal(err)
565		}
566	
567		store2 := reopenPersistent(t, dir)
568		h2 := NewHandler(store2)
569		events := allEvents(t, h2, "gw")
570		if len(events) != 3 {
571			t.Fatalf("uncommitted batch partially visible: %+v", events)
572		}
573		// The batch never committed, so resubmitting it is a fresh 202 at seq 4.
574		r := doRequest(t, h2, http.MethodPost, "/v1/devices/gw/replay",
575			replayBody("lost", sample("l1", "2024-01-04T00:00:00Z", `{"v":4}`)))
576		if r.Code != http.StatusAccepted {
577			t.Fatalf("uncommitted batch retry = %d, want 202", r.Code)
578		}
579		receipt := decodeBody[receiptResponse](t, r)
580		if receipt.Samples[0].Sequence != 4 {
581			t.Fatalf("sequence = %d, want 4", receipt.Samples[0].Sequence)
582		}
583	}
584	
585	// --- durable mode keeps atomicity under concurrency -------------------------
586	
587	func TestPersistentConcurrentWrites(t *testing.T) {
588		dir := t.TempDir()
589		store := openPersistent(t, dir)
590		h := NewHandler(store)
591		mustRegister(t, h, "gw")
592	
593		var start, wg sync.WaitGroup
594		start.Add(1)
595		for g := 0; g < 16; g++ {
596			wg.Add(1)
597			go func(g int) {
598				defer wg.Done()
599				start.Wait()
600				samples := make([]string, 4)
601				for i := range samples {
602					samples[i] = sample(fmt.Sprintf("g%d-e%d", g, i), "2024-01-02T10:00:00Z", fmt.Sprintf(`{"g":%d}`, g))
603				}
604				r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay", replayBody(fmt.Sprintf("batch-g%d", g), samples...))
605				if r.Code != http.StatusAccepted {
606					t.Errorf("group %d = %d: %s", g, r.Code, r.Body.String())
607				}
608			}(g)
609		}
610		codes := map[int]int{}
611		var codesMu sync.Mutex
612		for c := 0; c < 10; c++ {
613			wg.Add(1)
614			go func() {
615				defer wg.Done()
616				start.Wait()
617				r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay",
618					replayBody("dup", sample("dup-event", "2024-01-02T10:00:00Z", `{"v":1}`)))
619				codesMu.Lock()
620				codes[r.Code]++
621				codesMu.Unlock()
622			}()
623		}
624		start.Done()
625		wg.Wait()
626		if codes[http.StatusAccepted] != 1 || codes[http.StatusOK] != 9 {
627			t.Fatalf("dup codes = %v", codes)
628		}
629		events := allEvents(t, h, "gw")
630		if len(events) != 16*4+1 {
631			t.Fatalf("events = %d, want %d", len(events), 16*4+1)
632		}
633		for i, event := range events {
634			if event.Sequence != int64(i+1) {
635				t.Fatalf("non-contiguous sequence at %d: %d", i, event.Sequence)
636			}
637		}
638	
639		// Restart: the same concurrent result must recover exactly.
640		if err := store.Close(); err != nil {
641			t.Fatal(err)
642		}
643		store2 := reopenPersistent(t, dir)
644		h2 := NewHandler(store2)
645		recovered := allEvents(t, h2, "gw")
646		if len(recovered) != len(events) {
647			t.Fatalf("recovered events = %d, want %d", len(recovered), len(events))
648		}
649		// Re-hammering the dup batch after restart is still a single first receipt.
650		r := doRequest(t, h2, http.MethodPost, "/v1/devices/gw/replay",
651			replayBody("dup", sample("dup-event", "2024-01-02T10:00:00Z", `{"v":1}`)))
652		if r.Code != http.StatusOK {
653			t.Fatalf("post-restart dup = %d, want 200", r.Code)
654		}
655	}
