186	func (h *handler) history(w http.ResponseWriter, r *http.Request) {
187		id := r.PathValue("id")
188		query := r.URL.Query()
189	
190		filter := HistoryFilter{}
191		if raw := strings.TrimSpace(query.Get("from")); raw != "" {
192			from, err := time.Parse(time.RFC3339, raw)
193			if err != nil {
194				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "from must be RFC3339 formatted"})
195				return
196			}
197			filter.From = from.UTC()
198		}
199		if raw := strings.TrimSpace(query.Get("to")); raw != "" {
200			to, err := time.Parse(time.RFC3339, raw)
201			if err != nil {
202				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "to must be RFC3339 formatted"})
203				return
204			}
205			filter.To = to.UTC()
206		}
207		if !filter.From.IsZero() && !filter.To.IsZero() && filter.From.After(filter.To) {
208			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "from must not be after to"})
209			return
210		}
211	
212		limit := 20
213		if raw := strings.TrimSpace(query.Get("limit")); raw != "" {
214			value, err := strconv.Atoi(raw)
215			if err != nil || value < 1 || value > 100 {
216				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "limit must be between 1 and 100"})
217				return
218			}
219			limit = value
220		}
221	
222		var startSeq, highWater int64
223		rawCursor := strings.TrimSpace(query.Get("cursor"))
224		if rawCursor != "" {
225			// An unknown device is always 404, even with a malformed or foreign
226			// cursor; cursor problems on a registered device are 400.
227			if !h.store.Exists(id) {
228				writeJSON(w, http.StatusNotFound, map[string]string{"error": ErrDeviceNotFound.Error()})
229				return
230			}
231			cursor, err := decodeCursor(rawCursor)
232			if err != nil || cursor.DeviceID != id ||
233				!cursor.From.Equal(filter.From) || !cursor.To.Equal(filter.To) ||
234				!bytes.Equal(cursor.IID, h.store.instanceID()) {
235				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid cursor"})
236				return
237			}
238			startSeq, highWater = cursor.StartSeq, cursor.HighWater
239		}
240	
241		events, appliedBound, nextStart, hasMore, err := h.store.History(id, filter, startSeq, highWater, limit)
242		if errors.Is(err, ErrDeviceNotFound) {
243			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
244			return
245		}
246		var gone *historyGoneError
247		if errors.As(err, &gone) {
248			writeJSON(w, http.StatusGone, map[string]any{
249				"error":            ErrHistoryGone.Error(),
250				"earliestSequence": gone.earliestSequence,
251			})
252			return
253		}
254		if err != nil {
255			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
256			return
257		}
258		highWater = appliedBound
259	
260		var nextCursor any
261		if hasMore {
262			nextCursor = encodeCursor(pageCursor{
263				DeviceID:  id,
264				From:      filter.From,
265				To:        filter.To,
266				HighWater: highWater,
267				StartSeq:  nextStart,
268				IID:       h.store.instanceID(),
269			})
270		}
271	
272		writeJSON(w, http.StatusOK, map[string]any{
273			"deviceId":   id,
274			"events":     events,
275			"nextCursor": nextCursor,
276		})
277	}
278	
279	func (h *handler) snapshot(w http.ResponseWriter, _ *http.Request) {
280		writeJSON(w, http.StatusOK, map[string]any{"devices": h.store.Snapshot()})
281	}
282	
283	// --- history retention ------------------------------------------------------
284	
285	func (h *handler) getRetention(w http.ResponseWriter, r *http.Request) {
286		status, err := h.store.GetRetention(r.PathValue("id"))
287		if errors.Is(err, ErrDeviceNotFound) {
288			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
289			return
290		}
291		if err != nil {
292			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
293			return
294		}
295		writeJSON(w, http.StatusOK, status)
296	}
297	
298	func (h *handler) setRetention(w http.ResponseWriter, r *http.Request) {
299		var request struct {
300			MaxEvents *int64 `json:"maxEvents"`
301		}
302		if err := decodeSingleJSON(r, &request); err != nil || request.MaxEvents == nil {
303			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "maxEvents is required as a single integer"})
304			return
305		}
306		maxEvents := *request.MaxEvents
307		if maxEvents < 0 || maxEvents > maxRetentionEvents {
308			writeJSON(w, http.StatusBadRequest, map[string]string{
309				"error": fmt.Sprintf("maxEvents must be between 0 and %d", maxRetentionEvents),
310			})
311			return
312		}
313		status, err := h.store.SetRetention(r.PathValue("id"), maxEvents)
314		if errors.Is(err, ErrDeviceNotFound) {
315			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
316			return
317		}
318		if errors.Is(err, ErrStorageUnavailable) {
319			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
320			return
321		}
322		if err != nil {
323			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
324			return
325		}
326		writeJSON(w, http.StatusOK, status)
327	}
