1	package fleet
2	
3	import (
4		"errors"
5		"sort"
6		"sync"
7		"time"
8	)
9	
10	var (
11		ErrDeviceNotFound  = errors.New("device not found")
12		ErrBatchConflict   = errors.New("batch conflicts with stored events")
13		ErrRuleNotFound    = errors.New("rule not found")
14		ErrAlertNotFound   = errors.New("alert not found")
15		ErrRuleConflict    = errors.New("rule already exists")
16		ErrVersionConflict = errors.New("rule version conflict")
17		ErrInvalidRule     = errors.New("invalid rule")
18		// ErrHistoryGone means a continuation cursor's start record was trimmed by
19		// the retention limit before the next page was read.
20		ErrHistoryGone = errors.New("cursor start no longer retained")
21	)
22	
23	// maxRetentionEvents bounds a per-device history retention setting.
24	const maxRetentionEvents = 10000
25	
26	// RetentionStatus reports a device's history retention settings and counters.
27	// MaxEvents 0 means unlimited. EarliestSequence is nil for an empty history;
28	// MaxSequence is the highest sequence ever received (0 before any sample) and
29	// never retreats, even after trimming.
30	type RetentionStatus struct {
31		MaxEvents        int64  `json:"maxEvents"`
32		RetainedEvents   int64  `json:"retainedEvents"`
33		EarliestSequence *int64 `json:"earliestSequence"`
34		MaxSequence      int64  `json:"maxSequence"`
35	}
36	
37	// Rule is a per-device threshold rule. It judges only samples accepted while
38	// enabled; it never backfills history. Device and ID are immutable after
39	// creation. Version starts at 1 and bumps on every successful update.
40	type Rule struct {
41		ID        string    `json:"id"`
42		Metric    string    `json:"metric"`
43		Trigger   float64   `json:"trigger"`
44		Recover   float64   `json:"recover"`
45		Enabled   bool      `json:"enabled"`
46		Version   int64     `json:"version"`
47		CreatedAt time.Time `json:"createdAt"`
48		UpdatedAt time.Time `json:"updatedAt"`
49	}
50	
51	// Alert is one threshold crossing. It retains the rule version and the
52	// metric/thresholds in force when it fired. A natural recovery records the
53	// recovery sample's sequence, value and observed time; an end caused by a rule
54	// update records the server time and reason instead.
55	type Alert struct {
56		ID                int64      `json:"id"`
57		RuleID            string     `json:"ruleId"`
58		RuleVersion       int64      `json:"ruleVersion"`
59		Metric            string     `json:"metric"`
60		Trigger           float64    `json:"trigger"`
61		Recover           float64    `json:"recover"`
62		Status            string     `json:"status"` // "active" | "ended"
63		TriggerSequence   int64      `json:"triggerSequence"`
64		TriggerValue      float64    `json:"triggerValue"`
65		TriggerObservedAt time.Time  `json:"triggerObservedAt"`
66		RecoverSequence   *int64     `json:"recoverSequence,omitempty"`
67		RecoverValue      *float64   `json:"recoverValue,omitempty"`
68		RecoverObservedAt *time.Time `json:"recoverObservedAt,omitempty"`
69		EndedAt           *time.Time `json:"endedAt,omitempty"`
70		EndReason         string     `json:"endReason,omitempty"` // "recovered" | "rule_changed"
71		AcknowledgedAt    *time.Time `json:"acknowledgedAt,omitempty"`
72	}
73	
74	const (
75		alertStatusActive    = "active"
76		alertStatusEnded     = "ended"
77		endReasonRecovered   = "recovered"
78		endReasonRuleChanged = "rule_changed"
79	)
80	
81	// ruleState pairs a rule with the id of its currently active alert (0 when
82	// none).
83	type ruleState struct {
84		rule          Rule
85		activeAlertID int64
86	}
87	
88	type Device struct {
89		ID            string             `json:"id"`
90		Site          string             `json:"site"`
91		RegisteredAt  time.Time          `json:"registeredAt"`
92		LastSeenAt    time.Time          `json:"lastSeenAt"`
93		LastTelemetry map[string]float64 `json:"lastTelemetry,omitempty"`
94	}
95	
96	// Event is a single telemetry sample retained in a device's history.
97	type Event struct {
98		Sequence   int64              `json:"sequence"`
99		ObservedAt time.Time          `json:"observedAt"`
100		Values     map[string]float64 `json:"values"`
101	}
102	
103	// Sample is one replayed sample, decoded from the replay request body.
104	type Sample struct {
105		EventID    string
106		ObservedAt time.Time
107		Values     map[string]float64
108	}
109	
110	// ReplayReceipt summarises the outcome of a replay batch.
111	type ReplayReceipt struct {
112		BatchID      string         `json:"batchId"`
113		NewCount     int            `json:"newCount"`
114		Duplicate    int            `json:"duplicateCount"`
115		SampleStatus []SampleStatus `json:"samples"`
116	}
117	
118	// SampleStatus reports the history sequence assigned to (or reused by) a sample.
119	type SampleStatus struct {
120		EventID   string `json:"eventId"`
121		Sequence  int64  `json:"sequence"`
122		Duplicate bool   `json:"duplicate"`
123	}
124	
125	// HistoryFilter narrows a history query by observed-time range. Zero times mean
126	// the bound is open.
127	type HistoryFilter struct {
128		From time.Time
129		To   time.Time
130	}
131	
132	// StoredBatch records the ordered samples an accepted batchId committed along
133	// with the receipt returned on first acceptance, so a repeated batchId can be
134	// checked for identical content and replayed with the original receipt.
135	type storedBatch struct {
136		samples []Sample
137		receipt ReplayReceipt
138	}
139	
140	// knownSample is the durable replay-deduplication record for one eventId. It is
141	// retained even after the event itself leaves history through the retention
142	// limit, so a trimmed sample re-submitted later is still recognised as a
143	// duplicate (same content) or a conflict (different content).
144	type knownSample struct {
145		sequence   int64
146		observedAt time.Time
147		values     map[string]float64
148	}
149	
150	type deviceState struct {
151		device         Device
152		events         []Event                // retained history, ascending sequence (events[i].Sequence = eventBase + i + 1)
153		eventBase      int64                  // number of oldest events removed by retention; sequence of events[0] is eventBase+1
154		maxEvents      int64                  // retention cap; 0 means unlimited
155		known          map[string]knownSample // eventId -> first sample ever received (survives trimming)
156		batches        map[string]storedBatch
157		rules          map[string]*ruleState
158		alerts         []*Alert // per-device, ordered by alert id (id = index + 1)
159		config         *configState
160		tasks          []*taskState          // per-device, ordered by task id (id = index + 1)
161		tasksByRequest map[string]*taskState // requestId -> first task
162		// taskReceipts binds each accepted diagnostic receiptId to the one task
163		// that first accepted it. A receipt number may be retried on its owning
164		// task but can never be accepted as a new receipt by another task of the
165		// same device. Configuration receipts live in a separate map and do not
166		// participate in this binding.
167		taskReceipts map[string]int64 // receiptId -> owning task id
168	}
169	
170	// maxSequence is the highest receive sequence ever assigned to the device. It
171	// never retreats: trimming removes events but keeps consuming nothing, and new
172	// samples continue after it.
173	func (state *deviceState) maxSequence() int64 {
174		return state.eventBase + int64(len(state.events))
175	}
176	
177	// earliestSequence returns the first currently retained sequence, or 0 when
178	// the history is empty.
179	func (state *deviceState) earliestSequence() int64 {
180		if len(state.events) == 0 {
181			return 0
182		}
183		return state.eventBase + 1
184	}
185	
186	// retentionStatus snapshots the retention view of the device.
187	func (state *deviceState) retentionStatus() RetentionStatus {
188		status := RetentionStatus{
189			MaxEvents:      state.maxEvents,
190			RetainedEvents: int64(len(state.events)),
191			MaxSequence:    state.maxSequence(),
192		}
193		if earliest := state.earliestSequence(); earliest != 0 {
194			status.EarliestSequence = &earliest
195		}
196		return status
197	}
198	
199	// planTrimThrough reports the cumulative count of oldest events that must be
200	// removed for the history to satisfy maxEvents after a write that leaves
201	// maxSequence at maxSeq. It only grows: raising the limit or going unlimited
202	// never brings trimmed events back.
203	func planTrimThrough(eventBase, maxSeq, maxEvents int64) int64 {
204		if maxEvents == 0 {
205			return eventBase
206		}
207		if through := maxSeq - maxEvents; through > eventBase {
208			return through
209		}
210		return eventBase
211	}
212	
213	// applyTrim drops oldest retained events through sequence trimThrough. It
214	// touches neither deduplication records nor any other device state.
215	func (state *deviceState) applyTrim(trimThrough int64) {
216		if trimThrough <= state.eventBase {
217			return
218		}
219		drop := trimThrough - state.eventBase
220		if drop > int64(len(state.events)) {
221			drop = int64(len(state.events))
222		}
223		// Drop the prefix without preserving its backing slots.
224		remaining := make([]Event, len(state.events)-int(drop))
225		copy(remaining, state.events[drop:])
226		state.events = remaining
227		state.eventBase += drop
228	}
229	
230	type Store struct {
231		mu      sync.RWMutex
232		devices map[string]*deviceState
233		now     func() time.Time
234	
235		// wal is nil in memory mode. When set, every mutation is appended and
236		// synced here before in-memory state changes or success is returned.
237		wal walSink
238		iid []byte // data-directory instance id bound into history cursors
239	}
240	
241	func NewStore() *Store {
242		return &Store{devices: make(map[string]*deviceState), now: time.Now}
243	}
244	
245	// instanceID identifies the backing data directory; cursors are scoped to it.
246	// It is nil in memory mode.
247	func (s *Store) instanceID() []byte {
248		s.mu.RLock()
249		defer s.mu.RUnlock()
250		return s.iid
251	}
252	
253	// Exists reports whether a device is registered.
254	func (s *Store) Exists(id string) bool {
255		s.mu.RLock()
256		defer s.mu.RUnlock()
257		_, ok := s.devices[id]
258		return ok
259	}
