261	func (s *Store) Register(id, site string) (Device, bool, error) {
262		s.mu.Lock()
263		defer s.mu.Unlock()
264		if state, ok := s.devices[id]; ok {
265			return cloneDevice(state.device), false, nil
266		}
267		now := s.now().UTC()
268		device := Device{ID: id, Site: site, RegisteredAt: now, LastSeenAt: now}
269		if s.wal != nil {
