271				ID: id, Site: site, RegisteredAt: now, LastSeenAt: now,
272			}); err != nil {
273				return Device{}, false, storageUnavailable(err)
274			}
275		}
276		s.devices[id] = &deviceState{
277			device:  device,
278			known:   make(map[string]knownSample),
279			batches: make(map[string]storedBatch),
280			rules:   make(map[string]*ruleState),
