296	// SetRetention changes the per-device history cap. A maxEvents of 0 removes
297	// the limit; values 1..maxRetentionEvents keep at most that many newest
298	// samples. Lowering the limit trims the oldest events immediately by receive
299	// sequence; raising it only affects future writes. Device activity, last
300	// telemetry, alerts and other devices are untouched.
301	func (s *Store) SetRetention(id string, maxEvents int64) (RetentionStatus, error) {
302		s.mu.Lock()
303		defer s.mu.Unlock()
304		state, ok := s.devices[id]
305		if !ok {
306			return RetentionStatus{}, ErrDeviceNotFound
307		}
308		trimThrough := planTrimThrough(state.eventBase, state.maxSequence(), maxEvents)
309		if s.wal != nil {
310			if err := s.wal.appendRecord(recRetention, walRetention{
311				DeviceID:    id,
312				MaxEvents:   maxEvents,
313				TrimThrough: trimThrough,
314			}); err != nil {
315				return RetentionStatus{}, storageUnavailable(err)
316			}
317		}
318		state.maxEvents = maxEvents
319		state.applyTrim(trimThrough)
320		return state.retentionStatus(), nil
321	}
