323	// RecordTelemetry stores a live telemetry sample in the device history. The
324	// sample has no caller-supplied eventId, so it is never a replay duplicate; its
325	// observed time is the server receive time.
326	func (s *Store) RecordTelemetry(id string, values map[string]float64) (Device, error) {
327		s.mu.Lock()
328		defer s.mu.Unlock()
329		state, ok := s.devices[id]
330		if !ok {
331			return Device{}, ErrDeviceNotFound
332		}
333		now := s.now().UTC()
334		sequence := state.maxSequence() + 1
335		trimThrough := planTrimThrough(state.eventBase, sequence, state.maxEvents)
336		eval := newAlertEvaluator(state)
337		eval.evaluate(sequence, now, values)
338		if s.wal != nil {
339			if err := s.wal.appendRecord(recTelemetry, walTelemetry{
340				DeviceID:    id,
341				Sequence:    sequence,
342				ObservedAt:  now,
343				Values:      values,
344				TrimThrough: trimThrough,
345				Alerts:      eval.created,
346				Ended:       eval.ended,
347			}); err != nil {
348				return Device{}, storageUnavailable(err)
349			}
350		}
351		state.events = append(state.events, Event{
352			Sequence:   sequence,
353			ObservedAt: now,
354			Values:     cloneTelemetry(values),
355		})
356		state.device.LastSeenAt = now
357		state.device.LastTelemetry = cloneTelemetry(values)
358		eval.commit()
359		state.applyTrim(trimThrough)
360		return cloneDevice(state.device), nil
361	}
