363	// Replay validates and commits a batch atomically. repeat is true when the
364	// batchId was already committed with identical content and the first receipt
365	// is returned unchanged. It returns ErrDeviceNotFound for an unknown device and
366	// ErrBatchConflict when any sample clashes with an existing eventId or the
367	// batchId was previously committed with different ordered content; in either
368	// conflict case no state changes.
369	func (s *Store) Replay(id, batchID string, samples []Sample) (receipt ReplayReceipt, repeat bool, err error) {
370		s.mu.Lock()
371		defer s.mu.Unlock()
372		state, ok := s.devices[id]
373		if !ok {
374			return ReplayReceipt{}, false, ErrDeviceNotFound
375		}
376	
377		if previous, exists := state.batches[batchID]; exists {
378			if !sameOrderedSamples(previous.samples, samples) {
379				return ReplayReceipt{}, false, ErrBatchConflict
380			}
381			return cloneReceipt(previous.receipt), true, nil
382		}
383	
384		// Validate every sample against the device's dedup memory before assigning
385		// anything, so a conflict rolls back without leaving sequences, events or
386		// receipts. A previously trimmed event is still known here: identical
387		// content stays a duplicate (and never re-enters history), different
388		// content still conflicts the whole batch.
389		type plan struct {
390			sample   Sample
391			sequence int64
392			dup      bool
393		}
394		planned := make([]plan, len(samples))
395		nextSequence := state.maxSequence() + 1
396		for i, sample := range samples {
397			if known, seen := state.known[sample.EventID]; seen {
398				if !sameInstant(known.observedAt, sample.ObservedAt) ||
399					!sameValues(known.values, sample.Values) {
400					return ReplayReceipt{}, false, ErrBatchConflict
401				}
402				planned[i] = plan{sample, known.sequence, true}
403				continue
404			}
405			planned[i] = plan{sample, nextSequence, false}
406			nextSequence++
407		}
408		maxSequence := nextSequence - 1
409		trimThrough := planTrimThrough(state.eventBase, maxSequence, state.maxEvents)
410	
411		// Build the receipt from the plan: only samples that matched a committed
412		// event before this batch are duplicates.
413		receipt = ReplayReceipt{BatchID: batchID, SampleStatus: make([]SampleStatus, 0, len(samples))}
414		for _, entry := range planned {
415			receipt.SampleStatus = append(receipt.SampleStatus, SampleStatus{
416				EventID:   entry.sample.EventID,
417				Sequence:  entry.sequence,
418				Duplicate: entry.dup,
419			})
420			if entry.dup {
421				receipt.Duplicate++
422			} else {
423				receipt.NewCount++
424			}
425		}
426	
427		// Evaluate the batch's new samples against the device's enabled rules, in
428		// array order (which is receive-sequence order). Duplicates never judge,
429		// create, end or refresh alerts. A trigger and a recovery inside one batch
430		// both produce alert changes, all committed together with the batch.
431		eval := newAlertEvaluator(state)
432		for _, entry := range planned {
433			if entry.dup {
434				continue
435			}
436			eval.evaluate(entry.sequence, entry.sample.ObservedAt, entry.sample.Values)
437		}
438	
439		// Durable commit point: the whole batch is one record, synced before any
440		// in-memory state changes and before success is reported. A failure here
441		// leaves sequences, history, receipts, device state and alert changes
442		// untouched.
443		lastNew := -1
444		for i, entry := range planned {
445			if !entry.dup {
446				lastNew = i
447			}
448		}
449		var committedAt time.Time
450		if s.wal != nil {
451			record := walReplay{
452				DeviceID:    id,
453				BatchID:     batchID,
454				Samples:     make([]walSample, len(samples)),
455				Receipt:     receipt,
456				TrimThrough: trimThrough,
457				Alerts:      eval.created,
458				Ended:       eval.ended,
459			}
460			for i, sample := range samples {
461				record.Samples[i] = walSample{
462					EventID:    sample.EventID,
463					ObservedAt: sample.ObservedAt,
464					Values:     sample.Values,
465				}
466			}
467			if lastNew >= 0 {
468				committedAt = s.now().UTC()
469				record.LastSeenAt = &committedAt
470				record.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
471			}
472			if err := s.wal.appendRecord(recReplay, record); err != nil {
473				return ReplayReceipt{}, false, storageUnavailable(err)
474			}
475		}
476	
477		// Commit: append new samples in array order. Every new sample registers in
478		// the durable dedup memory, even when the retention limit immediately
479		// trims its event out of history.
480		for _, entry := range planned {
481			if entry.dup {
482				continue
483			}
484			state.events = append(state.events, Event{
485				Sequence:   entry.sequence,
486				ObservedAt: entry.sample.ObservedAt,
487				Values:     cloneTelemetry(entry.sample.Values),
488			})
489			state.known[entry.sample.EventID] = knownSample{
490				sequence:   entry.sequence,
491				observedAt: entry.sample.ObservedAt,
492				values:     cloneTelemetry(entry.sample.Values),
493			}
494		}
495	
496		committed := make([]Sample, len(samples))
497		copy(committed, samples)
498		for i := range committed {
499			committed[i].Values = cloneTelemetry(samples[i].Values)
500		}
501		state.batches[batchID] = storedBatch{samples: committed, receipt: cloneReceipt(receipt)}
502	
503		if lastNew >= 0 {
504			if s.wal == nil {
505				committedAt = s.now().UTC()
506			}
507			state.device.LastSeenAt = committedAt
508			state.device.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
509		}
510		eval.commit()
511		// Enforce the retention limit after the whole batch is accepted: all new
512		// samples judged, kept their assigned sequences and appear on the receipt;
513		// only the oldest excess events leave history.
514		state.applyTrim(trimThrough)
515		return receipt, false, nil
516	}
517	
518	func cloneReceipt(receipt ReplayReceipt) ReplayReceipt {
519		receipt.SampleStatus = append([]SampleStatus(nil), receipt.SampleStatus...)
520		return receipt
521	}
