524	
525	// ruleUpdate carries the mutable fields of a rule update. A nil pointer leaves
526	// the field unchanged.
527	type ruleUpdate struct {
528		Metric  *string
529		Trigger *float64
530		Recover *float64
531		Enabled *bool
532	}
