541	
542	// CreateRule registers a new enabled rule on a device. Version starts at 1.
543	// It returns ErrDeviceNotFound for an unknown device and ErrRuleConflict when
544	// the device already has a rule with that id.
545	func (s *Store) CreateRule(id, ruleID, metric string, trigger, recover float64) (Rule, error) {
546		s.mu.Lock()
547		defer s.mu.Unlock()
548		state, ok := s.devices[id]
549		if !ok {
550			return Rule{}, ErrDeviceNotFound
551		}
552		if _, exists := state.rules[ruleID]; exists {
553			return Rule{}, ErrRuleConflict
554		}
555		now := s.now().UTC()
556		rule := Rule{
557			ID: ruleID, Metric: metric, Trigger: trigger, Recover: recover,
558			Enabled: true, Version: 1, CreatedAt: now, UpdatedAt: now,
559		}
560		if s.wal != nil {
561			if err := s.wal.appendRecord(recRule, walRule{DeviceID: id, Rule: rule}); err != nil {
562				return Rule{}, storageUnavailable(err)
563			}
564		}
565		state.rules[ruleID] = &ruleState{rule: rule}
566		return cloneRule(rule), nil
567	}
568	
569	// UpdateRule applies a version-checked optimistic update. A version mismatch
570	// returns ErrVersionConflict with state unchanged. Every successful update
571	// bumps the version by one and immediately ends the rule's active alert (if
572	// any) with reason rule_changed; the rule starts again with no active alert.
573	func (s *Store) UpdateRule(id, ruleID string, update ruleUpdate, version int64) (Rule, []*Alert, error) {
574		s.mu.Lock()
575		defer s.mu.Unlock()
576		state, ok := s.devices[id]
577		if !ok {
578			return Rule{}, nil, ErrDeviceNotFound
579		}
580		rs, ok := state.rules[ruleID]
581		if !ok {
582			return Rule{}, nil, ErrRuleNotFound
583		}
584		if rs.rule.Version != version {
585			return Rule{}, nil, ErrVersionConflict
586		}
587	
588		updated := rs.rule
589		if update.Metric != nil {
590			updated.Metric = *update.Metric
591		}
592		if update.Trigger != nil {
593			updated.Trigger = *update.Trigger
594		}
595		if update.Recover != nil {
596			updated.Recover = *update.Recover
597		}
598		if update.Enabled != nil {
599			updated.Enabled = *update.Enabled
600		}
601		if updated.Recover >= updated.Trigger {
602			return Rule{}, nil, ErrInvalidRule
603		}
604	
605		// End the active alert of the old version before publishing the new one.
606		// Everything is computed from copies first and applied to live state only
607		// after the durable commit below, so a write failure (503) leaves the old
608		// rule, its active-alert pointer and the alert itself untouched; later
609		// samples keep judging against the pre-update rule.
610		var ended []*Alert
611		if rs.activeAlertID != 0 {
612			alert := cloneAlert(*state.alerts[rs.activeAlertID-1])
613			alert.Status = alertStatusEnded
614			alert.EndReason = endReasonRuleChanged
615			now := s.now().UTC()
616			alert.EndedAt = &now
617			ended = append(ended, &alert)
618		}
619	
620		updated.Version++
621		updated.UpdatedAt = s.now().UTC()
622	
623		if s.wal != nil {
624			if err := s.wal.appendRecord(recRule, walRule{DeviceID: id, Rule: updated, Ended: ended}); err != nil {
625				return Rule{}, nil, storageUnavailable(err)
626			}
627		}
628		// Commit point passed: publish the new rule, clear the rule's active-alert
629		// pointer and end its alert as one commit unit.
630		rs.activeAlertID = 0
631		rs.rule = updated
632		for _, alert := range ended {
633			state.alerts[alert.ID-1] = alert
634		}
635		return cloneRule(updated), cloneAlerts(ended), nil
636	}
637	
638	// GetRule returns one rule.
639	func (s *Store) GetRule(id, ruleID string) (Rule, error) {
640		s.mu.RLock()
641		defer s.mu.RUnlock()
642		state, ok := s.devices[id]
643		if !ok {
644			return Rule{}, ErrDeviceNotFound
645		}
646		rs, ok := state.rules[ruleID]
647		if !ok {
648			return Rule{}, ErrRuleNotFound
649		}
650		return cloneRule(rs.rule), nil
651	}
