653	// ListRules returns a device's rules, ordered by rule id.
654	func (s *Store) ListRules(id string) ([]Rule, error) {
655		s.mu.RLock()
656		defer s.mu.RUnlock()
657		state, ok := s.devices[id]
658		if !ok {
659			return nil, ErrDeviceNotFound
660		}
661		rules := make([]Rule, 0, len(state.rules))
662		for _, rs := range state.rules {
663			rules = append(rules, cloneRule(rs.rule))
664		}
665		sort.Slice(rules, func(i, j int) bool { return rules[i].ID < rules[j].ID })
666		return rules, nil
667	}
