669	// AckAlert records the server time of the first acknowledgment. Repeated
670	// acknowledgments keep the original time and write nothing. It returns
671	// ErrDeviceNotFound for an unknown device and ErrAlertNotFound for an unknown
672	// alert id.
673	func (s *Store) AckAlert(id string, alertID int64) (Alert, error) {
674		s.mu.Lock()
675		defer s.mu.Unlock()
676		state, ok := s.devices[id]
677		if !ok {
678			return Alert{}, ErrDeviceNotFound
679		}
680		if alertID < 1 || int(alertID) > len(state.alerts) {
681			return Alert{}, ErrAlertNotFound
682		}
683		alert := state.alerts[alertID-1]
684		if alert.AcknowledgedAt != nil {
685			return cloneAlert(*alert), nil
686		}
687		now := s.now().UTC()
688		if s.wal != nil {
689			if err := s.wal.appendRecord(recAlertAck, walAlertAck{
690				DeviceID: id, AlertID: alertID, AcknowledgedAt: now,
691			}); err != nil {
692				return Alert{}, storageUnavailable(err)
693			}
694		}
695		alert.AcknowledgedAt = &now
696		return cloneAlert(*alert), nil
697	}
