699	// ListAlerts returns a device's alerts with the given filters, ordered by
700	// alert id.
701	func (s *Store) ListAlerts(id string, filter AlertFilter) ([]Alert, error) {
702		s.mu.RLock()
703		defer s.mu.RUnlock()
704		state, ok := s.devices[id]
705		if !ok {
706			return nil, ErrDeviceNotFound
707		}
708		if filter.RuleID != "" {
709			if _, ok := state.rules[filter.RuleID]; !ok {
710				return nil, ErrRuleNotFound
711			}
712		}
713		alerts := make([]Alert, 0, len(state.alerts))
714		for _, alert := range state.alerts {
715			if filter.RuleID != "" && alert.RuleID != filter.RuleID {
716				continue
717			}
718			if filter.Status != "" && alert.Status != filter.Status {
719				continue
720			}
721			if filter.Acknowledged != nil {
722				acknowledged := alert.AcknowledgedAt != nil
723				if *filter.Acknowledged != acknowledged {
724					continue
725				}
726			}
727			alerts = append(alerts, cloneAlert(*alert))
728		}
729		return alerts, nil
730	}
731	
732	// alertEvaluator applies accepted samples to a device's enabled rules without
733	// mutating state until commit. It tracks which rule currently has an active
734	// alert so a trigger and a recovery inside the same batch are both handled in
735	// order.
736	type alertEvaluator struct {
737		state        *deviceState
738		activeByRule map[string]int64 // ruleID -> active alert id (0 when none)
739		created      []*Alert
740		ended        []*Alert
741		nextID       int64
742	}
743	
744	func newAlertEvaluator(state *deviceState) *alertEvaluator {
745		eval := &alertEvaluator{
746			state:        state,
747			activeByRule: make(map[string]int64, len(state.rules)),
748			nextID:       int64(len(state.alerts)) + 1,
749		}
750		for id, rs := range state.rules {
751			eval.activeByRule[id] = rs.activeAlertID
752		}
753		return eval
754	}
755	
756	// evaluate judges one accepted sample. A value at or above the trigger opens
757	// an alert (or keeps the existing one); a value at or below the recovery
758	// threshold ends the active alert; anything in between or a missing metric
759	// leaves state unchanged.
760	func (eval *alertEvaluator) evaluate(seq int64, observedAt time.Time, values map[string]float64) {
761		for _, rs := range eval.state.rules {
762			if !rs.rule.Enabled {
763				continue
764			}
765			value, ok := values[rs.rule.Metric]
766			if !ok {
767				continue
768			}
769			activeID := eval.activeByRule[rs.rule.ID]
770			if value >= rs.rule.Trigger && activeID == 0 {
771				alert := &Alert{
772					ID:                eval.nextID,
773					RuleID:            rs.rule.ID,
774					RuleVersion:       rs.rule.Version,
775					Metric:            rs.rule.Metric,
776					Trigger:           rs.rule.Trigger,
777					Recover:           rs.rule.Recover,
778					Status:            alertStatusActive,
779					TriggerSequence:   seq,
780					TriggerValue:      value,
781					TriggerObservedAt: observedAt,
782				}
783				eval.nextID++
784				eval.created = append(eval.created, alert)
785				eval.activeByRule[rs.rule.ID] = alert.ID
786			} else if value <= rs.rule.Recover && activeID != 0 {
787				var source *Alert
788				if activeID <= int64(len(eval.state.alerts)) {
789					source = eval.state.alerts[activeID-1]
790				} else {
791					source = eval.created[activeID-int64(len(eval.state.alerts))-1]
792				}
793				alert := cloneAlert(*source)
794				alert.Status = alertStatusEnded
795				alert.EndReason = endReasonRecovered
796				alert.RecoverSequence = &seq
797				alert.RecoverValue = &value
798				alert.RecoverObservedAt = &observedAt
799				eval.ended = append(eval.ended, &alert)
800				eval.activeByRule[rs.rule.ID] = 0
801			}
802		}
803	}
804	
805	// commit publishes the planned alert changes to the device state.
806	func (eval *alertEvaluator) commit() {
807		applyAlertChanges(eval.state, eval.created, eval.ended)
808	}
809	
810	// applyAlertChanges appends created alerts and replaces ended ones, keeping
811	// each rule's active-alert pointer in sync. It is shared by live evaluation
812	// and WAL recovery.
813	func applyAlertChanges(state *deviceState, created, ended []*Alert) {
814		for _, alert := range created {
815			state.alerts = append(state.alerts, alert)
816			if rs, ok := state.rules[alert.RuleID]; ok {
817				rs.activeAlertID = alert.ID
818			}
819		}
820		for _, alert := range ended {
821			state.alerts[alert.ID-1] = alert
822			if rs, ok := state.rules[alert.RuleID]; ok && rs.activeAlertID == alert.ID {
823				rs.activeAlertID = 0
824			}
825		}
826	}
827	
828	func cloneRule(rule Rule) Rule {
829		return rule
830	}
831	
832	func cloneAlert(alert Alert) Alert {
833		if alert.RecoverSequence != nil {
834			seq := *alert.RecoverSequence
835			alert.RecoverSequence = &seq
836		}
837		if alert.RecoverValue != nil {
838			value := *alert.RecoverValue
839			alert.RecoverValue = &value
840		}
841		if alert.RecoverObservedAt != nil {
842			t := *alert.RecoverObservedAt
843			alert.RecoverObservedAt = &t
844		}
845		if alert.EndedAt != nil {
846			t := *alert.EndedAt
847			alert.EndedAt = &t
848		}
849		if alert.AcknowledgedAt != nil {
850			t := *alert.AcknowledgedAt
851			alert.AcknowledgedAt = &t
852		}
853		return alert
854	}
855	
856	func cloneAlerts(alerts []*Alert) []*Alert {
857		if alerts == nil {
858			return nil
859		}
860		cloned := make([]*Alert, len(alerts))
861		for i, alert := range alerts {
862			c := cloneAlert(*alert)
863			cloned[i] = &c
864		}
865		return cloned
866	}
867	
868	// historyGoneError carries the current earliest retained sequence alongside
869	// ErrHistoryGone so a 410 response can tell the client where the surviving
870	// history resumes.
871	type historyGoneError struct {
872		earliestSequence int64
873	}
874	
875	func (e *historyGoneError) Error() string { return ErrHistoryGone.Error() }
876	func (e *historyGoneError) Unwrap() error { return ErrHistoryGone }
877	
878	// History returns one page of a device's event history. startSeq is the first
879	// receive sequence to scan (1 or 0 for the first page, which begins at the
880	// current earliest retained event); limit caps the number of matching events
881	// returned. bound pins the scan to sequences no larger than bound; a zero
882	// bound means "current maximum", which is then returned so callers can pin
883	// subsequent pages. nextStart is the sequence a following page should start at
884	// when hasMore is true. Retention may have removed the start of a continuation
885	// page: then ErrHistoryGone is returned with the current earliest sequence, so
886	// the missing range is never skipped silently. Concurrent writes cannot skip
887	// or duplicate rows within a paged walk.
888	func (s *Store) History(id string, filter HistoryFilter, startSeq, bound int64, limit int) (events []Event, appliedBound, nextStart int64, hasMore bool, err error) {
889		s.mu.RLock()
890		defer s.mu.RUnlock()
891		state, ok := s.devices[id]
892		if !ok {
893			return nil, 0, 0, false, ErrDeviceNotFound
894		}
895		highWater := state.maxSequence()
896		if bound == 0 {
897			bound = highWater
898		}
899		continuation := startSeq > 0
900		if !continuation {
901			startSeq = state.earliestSequence()
902			if startSeq == 0 {
903				startSeq = 1
904			}
905		} else if startSeq < state.earliestSequence() || startSeq > state.maxSequence() {
906			// The exact record the continuation starts at (or a prefix containing
907			// it) was trimmed. Report 410 with the live window's first sequence
908			// instead of silently resuming partway through the pinned range.
909			return nil, bound, 0, false, &historyGoneError{earliestSequence: state.earliestSequence()}
910		}
911		events = make([]Event, 0, limit)
912		for seq := startSeq; seq <= bound; seq++ {
913			event := state.events[seq-1-state.eventBase]
914			if !filter.From.IsZero() && event.ObservedAt.Before(filter.From) {
915				continue
916			}
917			if !filter.To.IsZero() && event.ObservedAt.After(filter.To) {
918				continue
919			}
920			if len(events) < limit {
921				events = append(events, cloneEvent(event))
922				continue
923			}
924			// This match belongs to the next page; resume scanning at its sequence
925			// so rows in the gap are never examined twice.
926			return events, bound, seq, true, nil
927		}
928		return events, bound, 0, false, nil
929	}
930	
931	func (s *Store) Snapshot() []Device {
932		s.mu.RLock()
933		defer s.mu.RUnlock()
934		result := make([]Device, 0, len(s.devices))
935		for _, state := range s.devices {
936			result = append(result, cloneDevice(state.device))
937		}
938		sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
939		return result
940	}
941	
942	func cloneDevice(device Device) Device {
943		device.LastTelemetry = cloneTelemetry(device.LastTelemetry)
944		return device
945	}
946	
947	func cloneEvent(event Event) Event {
948		event.Values = cloneTelemetry(event.Values)
949		return event
950	}
951	
952	func cloneTelemetry(values map[string]float64) map[string]float64 {
953		if values == nil {
954			return nil
955		}
956		cloned := make(map[string]float64, len(values))
957		for key, value := range values {
958			cloned[key] = value
959		}
960		return cloned
961	}
962	
963	// sameInstant compares times as UTC instants.
964	func sameInstant(a, b time.Time) bool {
965		return a.UTC().Equal(b.UTC())
966	}
967	
968	// sameValues compares metric maps by key and value.
969	func sameValues(a, b map[string]float64) bool {
970		if len(a) != len(b) {
971			return false
972		}
973		for key, value := range a {
974			other, ok := b[key]
975			if !ok || value != other {
976				return false
977			}
978		}
979		return true
980	}
981	
982	// sameOrderedSamples reports whether two batches carry the same samples in the
983	// same order, compared as UTC instants and key/value maps.
984	func sameOrderedSamples(a, b []Sample) bool {
985		if len(a) != len(b) {
986			return false
987		}
988		for i := range a {
989			if a[i].EventID != b[i].EventID ||
990				!sameInstant(a[i].ObservedAt, b[i].ObservedAt) ||
991				!sameValues(a[i].Values, b[i].Values) {
992				return false
993			}
994		}
995		return true
996	}
997

