666	func TestConcurrentReplays(t *testing.T) {
667		h := NewHandler(NewStore())
668		mustRegister(t, h, "gw")
669	
670		const groups = 20
671		const perGroup = 5
672		var start sync.WaitGroup
673		start.Add(1)
674		var wg sync.WaitGroup
675	
676		// Distinct batches, globally unique eventIds.
677		for g := 0; g < groups; g++ {
678			wg.Add(1)
679			go func(g int) {
680				defer wg.Done()
681				start.Wait()
682				samples := make([]string, perGroup)
683				for i := 0; i < perGroup; i++ {
684					samples[i] = sample(fmt.Sprintf("g%d-e%d", g, i), "2024-01-02T10:00:00Z", fmt.Sprintf(`{"g":%d,"i":%d}`, g, i))
685				}
686				r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay", replayBody(fmt.Sprintf("batch-g%d", g), samples...))
687				if r.Code != http.StatusAccepted {
688					t.Errorf("group %d status = %d: %s", g, r.Code, r.Body.String())
689				}
690			}(g)
691		}
692	
693		// Same batchId + identical content hammered concurrently: exactly one 202,
694		// the rest 200, never 409.
695		const dupCallers = 8
696		var codesMu sync.Mutex
697		codes := map[int]int{}
698		for c := 0; c < dupCallers; c++ {
699			wg.Add(1)
700			go func() {
701				defer wg.Done()
702				start.Wait()
703				r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay",
704					replayBody("dup-batch", sample("dup-event", "2024-01-02T10:00:00Z", `{"v":1}`)))
705				codesMu.Lock()
706				codes[r.Code]++
707				codesMu.Unlock()
708				if r.Code != http.StatusAccepted && r.Code != http.StatusOK {
709					t.Errorf("duplicate batch status = %d: %s", r.Code, r.Body.String())
710				}
711			}()
712		}
713	
714		start.Done()
715		wg.Wait()
716	
717		if codes[http.StatusAccepted] != 1 || codes[http.StatusOK] != dupCallers-1 {
718			t.Fatalf("dup-batch codes = %v, want one 202 and %d 200", codes, dupCallers-1)
719		}
720	
721		events := allEvents(t, h, "gw")
722		want := groups*perGroup + 1
723		if len(events) != want {
724			t.Fatalf("committed events = %d, want %d", len(events), want)
725		}
726		seen := make(map[int64]bool, len(events))
727		for _, event := range events {
728			if seen[event.Sequence] {
729				t.Fatalf("duplicate sequence %d", event.Sequence)
730			}
731			seen[event.Sequence] = true
732		}
733		for seq := int64(1); seq <= int64(want); seq++ {
734			if !seen[seq] {
735				t.Fatalf("sequence %d missing; allocation was not contiguous", seq)
736			}
737		}
738	}
